from nix_scribe.lib.context import SystemContext
from nix_scribe.modules.nixos.networking.networking import Networking
from nix_scribe.scanners.networking.networking import networking

MOCK_HOSTS = """
127.0.0.1 localhost
::1 localhost
127.0.1.1 my-hostname
192.168.1.50 server.internal server
"""

MOCK_RESOLV_STATIC = """
nameserver 1.1.1.1
nameserver 8.8.8.8
search internal.net
domain internal.net
"""

MOCK_RESOLV_DYNAMIC = """
# Generated by NetworkManager
nameserver 192.168.1.1
"""

MOCK_TIMESYNCD = """
[Time]
NTP=0.nixos.pool.ntp.org 1.nixos.pool.ntp.org
"""


def test_networking_scanner_empty(tmp_path, monkeypatch):
    context = SystemContext(tmp_path)
    monkeypatch.setattr(context.systemctl, "is_enabled", lambda _: False)
    mod = networking.scan(context)
    assert isinstance(mod, Networking)
    assert mod.useDHCP is False
    assert mod.to_dict() == {"useDHCP": False}


def test_networking_scanner(tmp_path, monkeypatch):
    assert networking.scan
    (tmp_path / "etc").mkdir()
    (tmp_path / "etc/hostname").write_text("my-hostname\n")
    (tmp_path / "etc/hosts").write_text(MOCK_HOSTS)
    (tmp_path / "etc/resolv.conf").write_text(MOCK_RESOLV_STATIC)
    (tmp_path / "etc/systemd").mkdir()
    (tmp_path / "etc/systemd/timesyncd.conf").write_text(MOCK_TIMESYNCD)

    context = SystemContext(tmp_path)
    monkeypatch.setattr(context.systemctl, "is_enabled", lambda x: x == "dhcpcd")

    mod = networking.scan(context)

    assert isinstance(mod, Networking)
    assert mod.hostName == "my-hostname"
    assert mod.enableIPv6 is True
    assert '"192.168.1.50"' in mod.hosts
    assert "server.internal" in mod.hosts['"192.168.1.50"']
    assert '"127.0.1.1"' not in mod.hosts
    assert mod.nameservers == ["1.1.1.1", "8.8.8.8"]
    assert mod.search == ["internal.net"]
    assert mod.domain == "internal.net"
    assert mod.useDHCP is True
    assert mod.resolve_claims() == {"dhcpcd"}
    assert mod.timeServers == ["0.nixos.pool.ntp.org", "1.nixos.pool.ntp.org"]

    fragment = mod.to_nix_fragment()
    data = fragment["networking"].value
    assert data["hostName"] == "my-hostname"
    assert "enableIpv6" not in data
    assert data["hosts"]['"192.168.1.50"'] == ["server.internal", "server"]
    assert data["nameservers"] == ["1.1.1.1", "8.8.8.8"]
    assert "useDHCP" not in data


def test_networking_scanner_disable_ipv6_sysctl(tmp_path, monkeypatch):
    (tmp_path / "etc/sysctl.d").mkdir(parents=True)
    (tmp_path / "etc/sysctl.d/99-disable-ipv6.conf").write_text(
        "net.ipv6.conf.all.disable_ipv6 = 1\n"
    )

    context = SystemContext(tmp_path)
    monkeypatch.setattr(context.systemctl, "is_enabled", lambda _: False)

    mod = networking.scan(context)
    assert isinstance(mod, Networking)
    assert mod.enableIPv6 is False

    fragment = mod.to_nix_fragment()
    assert fragment["networking"].value["enableIpv6"] is False


def test_networking_scanner_dynamic_resolv(tmp_path, monkeypatch):
    assert networking.scan
    (tmp_path / "etc").mkdir()
    (tmp_path / "etc/resolv.conf").write_text(MOCK_RESOLV_DYNAMIC)

    context = SystemContext(tmp_path)
    monkeypatch.setattr(context.systemctl, "is_enabled", lambda _: False)

    mod = networking.scan(context)
    assert isinstance(mod, Networking)
    assert mod.nameservers == []
    assert mod.to_dict() == {"useDHCP": False}
